arguments.query:
query AutomationSmoke {
  graphInfo { version readOnly maxDepth maxComplexity maxFields maxPageSize }
  stats { games activeGames studios platforms content publishedContent collections }
  games(first: 3, offset: 0, orderBy: "id", orderDir: "desc") {
    nodes { id name slug status studio { id name slug } platforms { id name slug } }
    pageInfo { total first offset hasMore nextOffset }
  }
  feeds(first: 3, offset: 0, status: "published", orderBy: "published_at", orderDir: "desc") {
    nodes { id title slug status publishedAt game { id name slug } }
    pageInfo { total first offset hasMore nextOffset }
  }
  contents(first: 3, offset: 0, type: "short", status: "published", orderBy: "published_at", orderDir: "desc") {
    nodes { id type title slug status publishedAt mediaType duration game { id name slug } }
    pageInfo { total first offset hasMore nextOffset }
  }
}
